INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (47, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', NULL, '(corridor OR passageway OR "clear width" OR "passage width") AND wheelchair AND ("co-production" OR "co-design" OR participatory OR "lived experience" OR "user involvement")', NULL, 'pubmed', 'scoping', 'none', 0, 0, 0, NULL, NULL, NULL, 0, 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06', 'GENUINE ABSENCE IN THE INDEX SEARCHED, not a query-shape failure. The identical subject terms without the co-production clause return 30 (logged as the R14 control). PubMed indexes corridor/passage-width work on wheelchair users and indexes none of it as co-produced. Co-1 on this parameter has to be sought outside PubMed -- DPO, housing and design venues. Prior held.', 0, 'Near-zero yield expected in PubMed specifically. Co-1 warrant is co-production, and co-produced disability research on building dimensions is published in design, housing and DPO grey venues rather than in a biomedical index. I expect 0-2 hits and expect that any hit will be participants TESTED rather than co-producing, which does not meet the Co-1 warrant. If the yield is 0 I must show by control query that the emptiness is about the venue, not the query shape (R14).');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (48, 'accessible-circulation-geometry', NULL, 'EN', 3, 'clinical', NULL, '(corridor OR passageway OR "clear width" OR "passage width") AND wheelchair', NULL, 'pubmed', 'scoping', 'none', 30, 30, 2, NULL, NULL, NULL, 0, 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06', 'Control held: 30 vs 0, so the Co-1 zero is a venue fact. Three of the 30 are already in the corpus (PMID 20434614=REF-00784, 20690862=REF-00971, 21657823=REF-00972), cross-filed under R9 rather than re-admitted. Two admitted (REF-00981, REF-00982). Two staged as candidates (PMID 40070282 evacuation simulation, 40767662 Brazilian dental-centre accessibility). The remaining 23 are off-parameter: nine autonomous-wheelchair navigation engineering papers and about ten of pure index noise -- one is a genetics paper on linkage of co-expressed genes (PMID 12446137), a useful measure of how loosely PubMed matched this AND-chain.', 0, 'Run as the R14 control for the Co-1 query: the same subject terms with the co-production clause removed, to establish whether that query returned 0 because of venue or because of query shape. Prior: a non-trivial count here (tens, not thousands) would show the subject is indexed and the Co-1 emptiness is a venue fact. Also expected to re-surface REF-00784/971/972, which R9 says to cross-file, not re-admit.');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (48, 'REF-00981', '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (48, 'REF-00982', '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (78, 48, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'McClain L, Beringer D, Kuhnert H, Priest J, Wilkinson S, Wyrick L. Restaurant wheelchair accessibility. Am J Occup Ther 1993', '10.5014/ajot.47.7.619', NULL, 3, 0, 'Surfaced by backward mining of REF-00981, not by a search; not retrieved, so nothing about its design or dimensions is established. An OT-journal accessibility measurement paper is a Co-2-adjacent lead worth resolving, but admitting it on a reference-list line would be the 2026-08-19 shape.', NULL, 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (79, 48, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'Software simulation of emergency evacuation and providing corrective measures in hospital buildings (PMID 40070282, doi 10.5055/jem.0838)', '10.5055/jem.0838', NULL, 3, 1, 'Its corridor claim is SIMULATED, not measured: Pathfinder software on a modelled hospital. Root would be derived_calculation from a model, and it states no corridor width for wheeled mobility users. Carries a real harm finding worth keeping -- with impediments in the building corridors, 36 percent of occupants could not be evacuated -- which is why it is staged rather than discarded.', NULL, 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (80, 48, 'accessible-circulation-geometry', NULL, 'REHOME', 'Accessibility for people with motor disabilities at CEOs in Brazil: an ecological study (PMID 40767662)', '10.1590/1807-3107bor-2025.vol39.080', NULL, 3, 0, 'Ecological study of accessibility INDICATORS across 889 Brazilian dental specialty centres over two cycles. Real and relevant to compliance evidence, but its unit is a programme indicator, not a corridor dimension.', NULL, 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (81, 48, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'REHOME', 'REF-00982 Paquet/Joseph/DSouza 2012 -- EXTRACTION RETRACTED from parameter 2 on an antagonist finding', '10.3233/wor-2012-0703-4098', NULL, 3, 0, 'The SOURCE stays admitted and slug-linked; what is retracted is its extraction against TERM-002 corridor width. Its own abstract states the objective is to demonstrate a re-sampling method -- doorway and clear floor space widths are the ILLUSTRATION, so root_type would be derived_calculation, not measurement_primary. And door width is TERM-021, a separate live term; clear floor space has no term at all. Filing it under TERM-002 because the abstract contains the string clear-width is exactly the conflation TERM-002''s own scope_note warns about for the es alias paso libre. Belongs to a future door-width or clear-floor-space cell.', NULL, 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-13-resea-REF-00981-MOB', 'REF-00981', 'MOB', 'No disabled participants. The units of study are TEN FITNESS FACILITIES assessed against an 82-item ADA checklist; wheelchair users are the population the facilities are judged against, not the population measured.', NULL, 'PROXY', NULL, '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', 'REF-00981', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-13-resea-REF-00982-MOB', 'REF-00982', 'MOB', 'Wheeled mobility device users, but reached by COMPUTER RE-SAMPLING of an existing anthropometric dataset rather than by measuring a new sample. The population is the right one; the route to it is simulation from prior measurement.', NULL, 'PARTIAL', NULL, '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', 'REF-00982', NULL);
INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', '1', 'REF-00981', NULL, 1, 0, '[]', NULL, '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', 'Pass RUN, not deferred: all 15 Crossref references read. NONE concerns corridor or passage width. The lineage is exercise physiology -- FES-evoked exercise, cardiovascular fitness after stroke, SCI exercise adherence -- plus two accessibility-compliance papers (Figoni 1998 on fitness-facility accessibility; McClain 1993 on restaurant wheelchair accessibility, Am J Occup Ther, doi 10.5014/ajot.47.7.619, staged as a candidate). This anchor has no citation lineage into circulation geometry. 0 connections is the finding, not a shortfall.');
INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', '2', 'REF-00982', NULL, 1, 0, '[]', NULL, '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', 'Pass ATTEMPTED and unavailable from the index: Crossref reports reference-count 0 and carries no reference array for this DOI (verified in payload ba1a87637524d7bd.json). WORK 41(S1) is a conference supplement whose references were not deposited. Backward mining needs the publisher PDF, not in hand. Recorded as unavailable rather than zero-yield.');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (40, 'REF-00981', 'narrow passageways', 'EN', 'abstract, Background', 'Ordinary community structures such as curbs, stairs and narrow passageways can present as major obstacles for individuals who are reliant on wheelchairs.', NULL, '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (41, 'REF-00981', 'free movement around exercise equipment', 'EN', 'abstract, Results', 'The areas of least compliance were access to and free movement around exercise equipment and full access to restrooms.', NULL, '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (42, 'REF-00982', 'clear floor space', 'EN', 'title', 'Computer re-sampling for demographically representative user populations in anthropometry: a case of doorway and clear floor space widths', NULL, '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "base_parameters" ("parameter_id", "term_id", "status", "merged_into", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (2, 'TERM-002', 'active', NULL, NULL, '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:06', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (5, 'REF-00784', 'accessible-circulation-geometry', 2, 'MOB', NULL, NULL, NULL, NULL, NULL, 'qualitative', 'code-compliant passageway width is insufficient for 10-100% of wheeled mobility users, task- and device-dependent', 'proportion of users unable to manoeuvre', 'Between 10% and 100% of users would not be able to maneuver in spaces that meet current Accessibility Guidelines for Buildings and Facilities specifications.', 'abstract, Conclusions (PMID 20434614 efetch, payload f5d94e0feaa8d48f)', NULL, 'measurement_primary', 'REF-00784', NULL, 'instrumented_physical_measurement', 'mixed', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Minimum passageway width IS this study''s outcome measure (''Minimum passageway widths for the 4 maneuverability tasks'') and the retrieved abstract states NO numeric width. The value recorded is the inadequacy the source does state, not a dimension it does not. CONTESTED SUBJECT, recorded not resolved: the four tasks are L-turn, 360-degree turn in place, and U-turns with and without a barrier -- passage width TO EXECUTE A TURN. Whether that is TERM-002 corridor width or TERM-003 turning circle is a real question that the abstract alone cannot settle; it is filed here because the measured quantity is a passageway width, and the note is left so a full-text read can move it.', '2026-09-13 01:07', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:07', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (6, 'REF-00971', 'accessible-circulation-geometry', 2, 'MOB', NULL, NULL, NULL, NULL, NULL, 'qualitative', 'no tested scooter completed all five configurations, one of which is a 180-degree corridor turn, within the space existing standards allow', 'pass/fail against existing standards', 'None of the scooters tested were capable of completing all manoeuvres within the space allowed by existing standards.', 'abstract, Results/Conclusions (PMID 20690862 efetch, payload 38b8b76bb0e8214d)', NULL, 'measurement_primary', 'REF-00971', NULL, 'instrumented_physical_measurement', 'scooter', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'MARKED CONTESTED ON AN ADVERSARIAL FINDING, which is the honest state rather than a defended one. The challenge: this source''s own harvested phrases are ''turning diameter'' (obs 6) and ''turning 180 degrees in a corridor'' (obs 7), and its sibling REF-00972 states a 1.5 m TURNING CIRCLE -- so the pair''s subject is arguably TERM-003, not TERM-002, and filing them under corridor width attaches turning-space measurement to a straight-clear-width parameter. What holds the row here: one of the five configurations measured is explicitly a corridor, and the quantity measured for it is the corridor dimension required. What weakens it: the quoted conclusion spans ALL FIVE configurations, not the corridor one alone. REF-00972 was deliberately NOT extracted on this parameter for the same reason -- its 1.5 m figure is a turning circle outright.', '2026-09-13 01:07', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:07', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (7, 'REF-00976', 'accessible-circulation-geometry', 2, 'MOB', NULL, NULL, NULL, NULL, NULL, 'qualitative', 'more than thirty centimetres of ENLARGEMENT over the surveyed stock (an increment, not a width)', 'cm of enlargement required, not absolute width', 'Enlargement in door openings and corridors by more than thirty centimeters is generally an actual resolution for realizing self supporting wheel chair lives in an averaged value.', 'abstract, item 3 (J-STAGE record for 10.3130/aija.69.33_1, payload d170cbf86507a07b)', NULL, 'measurement_primary', 'REF-00976', NULL, 'field_observation', 'mixed', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Graded qualitative, not numerical, ON PURPOSE. Thirty centimetres is a required increment over surveyed Japanese housing stock, not a corridor width; numerical would place it in a field meaning ''the value claimed for this parameter'' and a later reader could take it as a width. The unit string carries the distinction so it survives the next reader. The source also states corridor widths and door openings in new Japanese housing are ''far away from the reasonable states''.', '2026-09-13 01:07', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:07', 'session_2026-09-13-research-batch-07-corridor-width');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (8, 'REF-00981', 'accessible-circulation-geometry', 2, 'MOB', NULL, NULL, NULL, NULL, NULL, 'absent', NULL, NULL, 'All surveyed facilities were found to be partially compliant, with none of the facilities being 100% compliant.', 'abstract, Results (PMID 25777328 efetch, payload 03f510fc785b6d45)', NULL, 'measurement_primary', 'REF-00981', NULL, 'field_observation', 'mixed', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'absent-confirmed', NULL, 'ABSENT is the honest grade and is itself the finding: an 82-item ADA compliance survey of ten facilities that names narrow passageways as a major obstacle and never reports a passageway dimension. Independently reached by the adversarial pass, which read the same payload and concluded the same grade.', '2026-09-13 01:07', 'session_2026-09-13-research-batch-07-corridor-width', '2026-09-13 01:07', 'session_2026-09-13-research-batch-07-corridor-width');
